test('lineDiscount with 10 units gets bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const expectedBulkDiscount = roundCents(total * 2.5 / 100);
  assert.equal(discount, expectedBulkDiscount);
});

test('lineDiscount with 9 units does not get bulk discount', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount with 11 units gets bulk discount', () => {
  const line = { qty: 11, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const expectedBulkDiscount = roundCents(total * 2.5 / 100);
  assert.equal(discount, expectedBulkDiscount);
});

test('lineDiscount with 100 units gets bulk discount', () => {
