  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const expectedBulkDiscount = roundCents(total * 2.5 / 100);
  assert.equal(discount, expectedBulkDiscount);
});

test('lineDiscount bulk discount is applied after base discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 0 };
  const total = lineTotal(line);
  const baseDiscount = roundCents(total * 10 / 100);
  const amountAfterBase = total - baseDiscount;
  const expectedBulkDiscount = roundCents(amountAfterBase * 2.5 / 100);
  const expectedTotal = baseDiscount + expectedBulkDiscount;
  const discount = lineDiscount(line);
  assert.equal(discount, expectedTotal);
});

test('lineDiscount bulk discount with 20% base discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 20, vatRate: 0 };
  const total = lineTotal(line);
  const baseDiscount = roundCents(total * 20 / 100);
  const amountAfterBase = total - baseDiscount;
  const expectedBulkDiscount = roundCents(amountAfterBase * 2.5 / 100);
  const expectedTotal = baseDiscount + expectedBulkDiscount;
  const discount = lineDiscount(line);
  assert.equal(discount, expectedTotal);
});

test('lineVat calculated on amount after both discounts', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const total = lineTotal(line);
  const baseDiscount = roundCents(total * 10 / 100);
  const amountAfterBase = total - baseDiscount;
  const bulkDiscount = roundCents(amountAfterBase * 2.5 / 100);
  const amountForVat = total - baseDiscount - bulkDiscount;
  const expectedVat = roundCents(amountForVat * 21 / 100);
  const vat = lineVat(line);
  assert.equal(vat, expectedVat);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 10 * 10000;
  const line1BulkDiscount = roundCents(line1Total * 2.5 / 100);
  const line2Total = 5 * 10000;
  assert.equal(totals.discount, line1BulkDiscount);
  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.total, totals.subtotal - totals.discount);
});

