  };
  const totals = invoiceTotals(invoice);
  const line1Total = 10 * 10000;
  const line1BulkDiscount = roundCents(line1Total * 2.5 / 100);
  const line2Total = 20 * 5000;
  const line2BulkDiscount = roundCents(line2Total * 2.5 / 100);
  assert.equal(totals.discount, line1BulkDiscount + line2BulkDiscount);
});

test('invoiceTotals bulk discount with base discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 15, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = 10 * 10000;
  const baseDiscount = roundCents(total * 15 / 100);
  const amountAfterBase = total - baseDiscount;
  const bulkDiscount = roundCents(amountAfterBase * 2.5 / 100);
  assert.equal(totals.discount, baseDiscount + bulkDiscount);
  assert.equal(totals.total, total - baseDiscount - bulkDiscount);
});

test('invoiceTotals bulk discount with VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = 10 * 10000;
  const bulkDiscount = roundCents(total * 2.5 / 100);
  const amountForVat = total - bulkDiscount;
  const expectedVat = roundCents(amountForVat * 21 / 100);
  assert.equal(totals.discount, bulkDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, total - bulkDiscount + expectedVat);
});

test('invoiceTotals bulk discount with base discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = 10 * 10000;
  const baseDiscount = roundCents(total * 10 / 100);
  const amountAfterBase = total - baseDiscount;
  const bulkDiscount = roundCents(amountAfterBase * 2.5 / 100);
  const amountForVat = total - baseDiscount - bulkDiscount;
  const expectedVat = roundCents(amountForVat * 21 / 100);
  assert.equal(totals.discount, baseDiscount + bulkDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, total - baseDiscount - bulkDiscount + expectedVat);
});

test('invoiceTotals mixed lines with and without bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
      { qty: 15, unitPrice: 10000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 10 * 10000;
  const line1Discount = roundCents(line1Total * 2.5 / 100);
  const line2Total = 5 * 10000;
  const line2Discount = 0;
  const line3Total = 15 * 10000;
  const line3BaseDiscount = roundCents(line3Total * 5 / 100);
  const line3AmountAfterBase = line3Total - line3BaseDiscount;
  const line3BulkDiscount = roundCents(line3AmountAfterBase * 2.5 / 100);
  const line3Discount = line3BaseDiscount + line3BulkDiscount;
  const totalDiscount = line1Discount + line2Discount + line3Discount;
  assert.equal(totals.subtotal, line1Total + line2Total + line3Total);
  assert.equal(totals.discount, totalDiscount);
});

test('lineDiscount bulk discount rounds correctly', () => {
  const line = { qty: 10, unitPrice: 333, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(Number.isInteger(discount), true);
});

test('lineDiscount with qty exactly 10 gets bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert(discount > 0, 'qty=10 should get bulk discount');
});

test('lineDiscount with qty 9 no bulk discount', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0, 'qty=9 should not get bulk discount');
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    lines: [
      { qty: 1000, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = 1000 * 1000;
  const expectedDiscount = roundCents(total * 2.5 / 100);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.total, total - expectedDiscount);
});

